  ];

  for (const root of roots) {
    const found = scan(root, 0);
    if (found) return found;
  }

  // 3) Variables environnement possibles.
  const envCandidates = [
    env.get("PREMIUM_DASHBOARD_OUTPUT"),
    env.get("premium_dashboard_output"),
    env.get("DASHBOARD_OUTPUT"),
    env.get("dashboard_output"),
    env.get("DASHBOARD_MODE"),
    env.get("dashboard_mode"),
    env.get("PREMIUM_DASHBOARD_MODE"),
    env.get("premium_dashboard_mode")
  ];
  for (const candidate of envCandidates) {
    const found = norm(candidate);
    if (found) return found;
  }

  // 4) Cache global en dernier uniquement.
  const cachedCandidates = [
    global.get("premium.dashboard_output"),
    global.get("premiumDashboardOutput"),
    global.get("config.premiumDashboardOutput"),
    global.get("dashboard.premium_output")
  ];
