 card.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{dirty=true;c[el.dataset.key]=el.type==='number'?Number(el.value):el.value;if(el.dataset.key==='entity')card.querySelector('[data-auto-unit]').value=autoUnit(c.entity);if(['mode','sessionMode'].includes(el.dataset.key))updateFields();});
 card.querySelector('[data-archive]').onclick=()=>{const saved=data?.items.some(i=>i.config.id===c.id);if(!saved){draft=draft.filter(i=>i.id!==c.id);}else{if(!c.archived&&!confirm(tr('Archiver cet appareil ? Son historique sera conservé et le suivi arrêté.','Archive this device? History will be kept and tracking stopped.')))return;c.archived=!c.archived;}dirty=true;editors();};updateFields();root.append(card);
