document.getElementById('custom_save').onclick=async()=>{
 draft=draft.map(({unit,sampleSeconds,...c})=>c);
 const hass=getHass();if(!hass?.callService){feedback(tr('Connexion directe à Home Assistant nécessaire pour enregistrer.','A direct Home Assistant connection is required to save.'));return;}
 if(draft.some(c=>!/^sensor\.[a-z0-9_]+$/.test(c.entity))){feedback(errors.invalid_or_duplicate_entity);return;}
 pending='r_'+Date.now();const request=pending;feedback(T.pending);render();
 try{await hass.callService('mqtt','publish',{topic:'smart_energy_finance/custom_consumption/config/set',payload:JSON.stringify({revision:baseRevision,request_id:request,items:draft}),qos:1,retain:false});setTimeout(()=>{if(pending===request){pending=null;feedback(tr('Aucune confirmation reçue. Vérifie la connexion MQTT puis recharge la page.','No confirmation received. Check MQTT connectivity, then reload the page.'));render();}},15000);}catch(e){pending=null;feedback(tr('Enregistrement impossible : ','Could not save: ')+e.message);render();}
};
let backupBusy=false,backupWait=null,restoreFile=null;
const backupPanel=document.createElement('div');backupPanel.className='panel';backupPanel.innerHTML='<details><summary style="cursor:pointer;font-weight:800">💾 '+tr('Sauvegarde et restauration','Backup and restore')+'</summary><p class="custom-note">'+tr('Sauvegarde les historiques Finance, les corrections enregistrées, les appareils, groupes et cycles Conso. Les réglages de l’add-on, les identifiants MQTT et la licence ne sont pas inclus. Après une restauration, les tarifs et entités de la configuration actuelle restent utilisés.','Back up Finance history, saved corrections, devices, groups and consumption cycles. Add-on settings, MQTT credentials and the licence are not included. After restoring, current configured tariffs and entities remain in use.')+'</p><div class="actions"><button class="btn" id="finance_backup_download">'+tr('Télécharger une sauvegarde','Download backup')+'</button><button class="btn" id="finance_backup_recovery">'+tr('Copie avant dernière restauration','Copy before last restore')+'</button></div><hr style="border-color:#26364c;margin:18px 0"><label>'+tr('Fichier de sauvegarde','Backup file')+'<input type="file" id="finance_backup_file" accept=".json,application/json"></label><label>'+tr('Données à restaurer','Data to restore')+'<select id="finance_backup_scope"><option value="all">'+tr('Finance et Conso','Finance and Consumption')+'</option><option value="finance">'+tr('Finance uniquement','Finance only')+'</option><option value="consumption">'+tr('Conso uniquement','Consumption only')+'</option></select></label><p id="finance_backup_preview" class="custom-note"></p><button class="btn" id="finance_backup_restore">'+tr('Vérifier et restaurer…','Validate and restore…')+'</button><p class="custom-note" id="finance_backup_status" role="status"></p></details>';settings.append(backupPanel);
const backupStatus=s=>document.getElementById('finance_backup_status').textContent=s;
function syncBackupButtons(){backupPanel.querySelectorAll('button,input,select').forEach(b=>b.disabled=backupBusy||!data?.premium);document.getElementById('finance_backup_restore').disabled=backupBusy||!data?.premium||!restoreFile;}
const backupErrors={invalid_backup:tr('Fichier incompatible ou données invalides.','Incompatible file or invalid data.'),no_recovery:tr('Aucune copie avant restauration n’est encore disponible.','No pre-restore copy is available yet.'),backup_too_large:tr('La sauvegarde dépasse la taille prise en charge.','Backup exceeds the supported size.'),transfer_expired:tr('Le transfert a expiré. Relance l’opération.','Transfer expired. Start again.'),missing_section:tr('La sauvegarde ne contient pas la partie sélectionnée.','Backup does not contain the selected section.'),restore_write_failed:tr('Échec de la restauration. La copie avant restauration est conservée.','Restore failed. The pre-restore copy is retained.'),revision_conflict:errors.revision_conflict};
function backupRequest(command){return new Promise((resolve,reject)=>{const hass=getHass();if(!hass?.callService){reject(Error(tr('Connexion Home Assistant nécessaire.','Home Assistant connection required.')));return;}const id='b_'+Date.now()+'_'+Math.random().toString(36).slice(2);const timer=setTimeout(()=>{if(backupWait?.id===id){backupWait=null;reject(Error(tr('Aucune confirmation du moteur. Vérifie MQTT et réessaie.','No engine confirmation. Check MQTT and retry.')));}},30000);backupWait={id,resolve,reject,timer};hass.callService('mqtt','publish',{topic:'smart_energy_finance/custom_consumption/config/set',payload:JSON.stringify({...command,request_id:id}),qos:1,retain:false}).catch(e=>{if(backupWait?.id===id){backupWait=null;clearTimeout(timer);reject(e);}});});}
function receiveBackup(r){if(!r||!backupWait||r.request_id!==backupWait.id)return;const wait=backupWait;backupWait=null;clearTimeout(wait.timer);if(r.status==='error')wait.reject(Error(backupErrors[r.error]||tr('Opération impossible : ','Operation failed: ')+r.error));else wait.resolve(r);}
function saveBackupFile(raw,recovery){const url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=(recovery?'Smart_Energy_Finance_Avant_Restauration_':'Smart_Energy_Finance_Sauvegarde_')+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function downloadBackup(recovery=false){if(backupBusy||!data?.premium)return;backupBusy=true;syncBackupButtons();render();try{backupStatus(tr('Préparation…','Preparing…'));const start=await backupRequest({action:'backup_start',recovery});let raw='';for(let i=0;i<start.total;i++){backupStatus(tr('Téléchargement ','Downloading ')+(i+1)+' / '+start.total);const r=await backupRequest({action:'backup_chunk',token:start.token,index:i});raw+=r.text;}JSON.parse(raw);saveBackupFile(raw,recovery);await backupRequest({action:'backup_finish',token:start.token});backupStatus(tr('Sauvegarde téléchargée.','Backup downloaded.'));}catch(e){backupStatus(e.message);}finally{backupBusy=false;syncBackupButtons();render();}}
document.getElementById('finance_backup_download').onclick=()=>downloadBackup();document.getElementById('finance_backup_recovery').onclick=()=>downloadBackup(true);
document.getElementById('finance_backup_file').onchange=async e=>{restoreFile=null;document.getElementById('finance_backup_preview').textContent='';const f=e.target.files?.[0];try{if(f){if(f.size>16000000)throw Error(backupErrors.backup_too_large);const raw=await f.text();if(raw.length>4000000)throw Error(backupErrors.backup_too_large);const b=JSON.parse(raw);if(b.format!=='smart-energy-finance-backup'||b.version!==1||!Number.isFinite(Date.parse(b.created_at)))throw Error(backupErrors.invalid_backup);restoreFile={raw,bundle:b};document.getElementById('finance_backup_preview').textContent=tr('Sauvegarde du ','Backup from ')+dateText(b.created_at)+' · '+(b.consumption?.items?.length||0)+' '+tr('appareils','devices');}}catch(e){backupStatus(e.message);}syncBackupButtons();};
function confirmRestore(info){return new Promise(resolve=>{dialog.innerHTML='<h2>'+tr('Confirmer la restauration','Confirm restore')+'</h2><p>'+tr('Sauvegarde du ','Backup from ')+esc(dateText(info.created_at))+'</p><p>'+esc({all:tr('Finance et Conso','Finance and Consumption'),finance:tr('Finance uniquement','Finance only'),consumption:tr('Conso uniquement','Consumption only')}[info.scope])+' · '+info.devices+' '+tr('appareils dans le fichier','devices in the file')+' · '+info.days+' '+tr('jours archivés Finance','archived Finance days')+'</p><p>'+tr('Les données sélectionnées seront remplacées, sans fusion. Une copie de l’état actuel sera enregistrée avant remplacement. Les consommations entre la date de sauvegarde et maintenant ne seront pas reconstituées.','Selected data will be replaced, without merging. A copy of the current state will be saved first. Consumption between the backup date and now will not be reconstructed.')+'</p><div class="actions"><button class="btn" id="backup_cancel">'+tr('Annuler','Cancel')+'</button><button class="btn" id="backup_confirm">'+tr('Restaurer ces données','Restore this data')+'</button></div>';const done=v=>{dialog.oncancel=null;dialog.close();resolve(v);};dialog.querySelector('#backup_cancel').onclick=()=>done(false);dialog.querySelector('#backup_confirm').onclick=()=>done(true);dialog.oncancel=e=>{e.preventDefault();done(false);};dialog.showModal();});}
document.getElementById('finance_backup_restore').onclick=async()=>{if(backupBusy||!data?.premium||!restoreFile)return;if(dirty||pending){backupStatus(tr('Enregistre d’abord tes réglages en cours.','Save your pending settings first.'));return;}backupBusy=true;syncBackupButtons();render();try{const raw=restoreFile.raw,scope=document.getElementById('finance_backup_scope').value,total=Math.ceil(raw.length/24000);const start=await backupRequest({action:'restore_start',scope,total});for(let i=0;i<total;i++){backupStatus(tr('Vérification ','Validating ')+(i+1)+' / '+total);await backupRequest({action:'restore_chunk',token:start.token,index:i,text:raw.slice(i*24000,(i+1)*24000)});}const info=await backupRequest({action:'restore_validate',token:start.token});if(!await confirmRestore(info)){backupStatus(tr('Restauration annulée.','Restore cancelled.'));return;}backupStatus(tr('Restauration…','Restoring…'));await backupRequest({action:'restore_commit',token:start.token});dirty=false;pending=null;draft=null;document.activeElement?.blur();signature='';refresh();backupStatus(tr('Restauration terminée. Finance se mettra à jour au prochain relevé.','Restore complete. Finance will refresh on the next reading.'));}catch(e){backupStatus(e.message);}finally{backupBusy=false;syncBackupButtons();render();}};

let signature='';
function refresh(){
 const hass=getHass();const states=hass?.states||(typeof STATES!=='undefined'?STATES:{});
 const entity=Object.values(states).find(s=>s.entity_id?.startsWith('sensor.smart_energy_finance_custom_consumption')&&Array.isArray(s.attributes?.items));
 const a=entity?.attributes;if(!a)return;
 const sig=JSON.stringify(a);if(sig===signature)return;signature=sig;data=a;receiveBackup(a.backup);syncBackupButtons();
 if(pending&&a.request_id===pending){pending=null;if(a.error)feedback(errors[a.error]||a.error);else{dirty=false;feedback(T.saved);}}
 // Live readings must never recreate inputs or close a native select menu.
 const incomingConfig=data.items.map(i=>({...i.config}));
 const editingField=document.activeElement?.matches('#sef_custom_settings input, #sef_custom_settings select');
 if(!dirty&&!pending&&!editingField){
  const configChanged=draft===null||JSON.stringify(draft)!==JSON.stringify(incomingConfig);
  baseRevision=data.revision;
  if(configChanged){draft=incomingConfig;editors();}
 }
 const list=document.getElementById('custom_entities');const entitiesHtml=Object.values(states).filter(s=>s.entity_id?.startsWith('sensor.')&&['W','kW','Wh','kWh'].includes(s.attributes?.unit_of_measurement)).map(s=>'<option value="'+esc(s.entity_id)+'">'+esc((s.attributes.friendly_name||s.entity_id)+' · '+s.attributes.unit_of_measurement)+'</option>').join('');
 if(list.innerHTML!==entitiesHtml)list.innerHTML=entitiesHtml;
 const statusList=document.getElementById('custom_state_entities');const statesHtml=Object.values(states).filter(s=>/^(binary_sensor|switch|sensor)\./.test(s.entity_id||'')).map(s=>'<option value="'+esc(s.entity_id)+'">'+esc(s.attributes?.friendly_name||s.entity_id)+'</option>').join('');if(statusList.innerHTML!==statesHtml)statusList.innerHTML=statesHtml;
 render();
}
