const inputEnv = String(msg.payload || "").trim();

let bip = 5;
let environnement = "Inconnu";

switch (inputEnv) {

    case "HAOS":
        bip = 1;
        environnement = "Home Assistant OS";
        break;

    case "Docker":
        bip = 2;
        environnement = "Docker";
        break;

    case "Linux":
        bip = 3;
        environnement = "Linux";
        break;

    case "Windows":
        bip = 4;
        environnement = "Windows";
        break;
}

// On garde seulement les informations nécessaires.
// Le deuxième chiffre Premium sera ajouté juste avant l'envoi.
msg.telemetry = {
    bipBase: bip,
    environnement: environnement
};

node.status({
    fill: "blue",
    shape: "dot",
    text: environnement
});

return msg;

// ============================================================
// SMART ENERGY FINANCE - TELEMETRIE GOOGLE
// ============================================================

// Informations conservées par "Analyse environnement"
const telemetry = msg.telemetry || {};

// Réponse reçue de https://ipwho.is/
const geo = msg.payload || {};


// ============================================================
// INSTALL ID
// ============================================================

const premium = global.get("premium") || {};

const installId =
    global.get("premium.install_id") ||
    premium.install_id ||
    "";

if (!installId) {

    node.status({
        fill: "red",
        shape: "ring",
        text: "install_id absent"
    });

    node.warn(
        "Télémétrie Smart Energy Finance : install_id absent"
    );

    return null;
}


// ============================================================
// PREMIUM
// ============================================================

const premiumActive =
    premium.active === true ||
    global.get("premium.active") === true;

const premiumDigit =
    premiumActive ? "1" : "0";

const bipFinal =
    String(telemetry.bipBase || 5) +
    premiumDigit;


// ============================================================
// VERSION SMART ENERGY FINANCE
// ============================================================

const version =
    env.get("SMART_ENERGY_FINANCE_VERSION") ||
    "";


// ============================================================
// GEOLOCALISATION
// ============================================================

let country = "";
let region = "";
let city = "";
let lat = "";
let lon = "";

if (geo.success === true) {

    country = geo.country || "";
    region = geo.region || "";
    city = geo.city || "";

    lat =
        geo.latitude !== undefined &&
            geo.latitude !== null
            ? geo.latitude
            : "";

    lon =
        geo.longitude !== undefined &&
            geo.longitude !== null
            ? geo.longitude
            : "";
}


// ============================================================
// PAYLOAD GOOGLE
// ============================================================

msg.payload = {

    // Obligatoire pour le Apps Script multi-module
    module: "finance",

    install_id: String(installId),

    bip: bipFinal,

    version: String(version),

    country: country,

    region: region,

    city: city,

    lat: lat,

    lon: lon
};


// ============================================================
// HEADERS POST GOOGLE
// ============================================================

msg.headers = {
    "Content-Type": "application/json"
};


// ============================================================
// REDIRECTION GOOGLE
// ============================================================

// Google Apps Script renvoie une redirection après traitement
// du POST.
//
// On ne suit pas cette redirection car l'enregistrement
// dans Google Sheets est déjà effectué.
//
// Cela évite que Node-RED refasse un POST vers
// script.googleusercontent.com et obtienne une erreur 405.

msg.followRedirects = false;


// ============================================================
// STATUS NODE
// ============================================================

let statusText =
    "v" + (version || "?") +
    " | BIP " + bipFinal;

if (city) {
    statusText += " | " + city;
}

node.status({
    fill: geo.success === true ? "green" : "yellow",
    shape: "dot",
    text: statusText
});


// ============================================================
// DEBUG LOG
// ============================================================

node.debug(
    "Smart Energy Finance télémétrie : " +
    "module=finance" +
    " version=" + (version || "inconnue") +
    " bip=" + bipFinal +
    " city=" + (city || "inconnue")
);


// ============================================================
// ENVOI
// ============================================================

return msg;
